import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Item Browser GUI","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/item/browser.md","filePath":"en/modules/item/browser.md","lastUpdated":0}`),a={name:`en/modules/item/browser.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="item-browser-gui" tabindex="-1">Item Browser GUI <a class="header-anchor" href="#item-browser-gui" aria-label="Permalink to “Item Browser GUI”">​</a></h1><p><code>/ei browse</code> opens a two-level browser: the first level lists item packs, clicking a pack icon opens the second level listing the items inside it, and a left click takes one piece into the inventory (Shift + left click takes a full stack).</p><p>Each level has its own layout file, both under <code>plugins/EmakiItem/gui/</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Level</th><th>Purpose</th></tr></thead><tbody><tr><td><code>pack_browser_gui.yml</code></td><td>First</td><td>Lists every item pack under <code>items/</code>.</td></tr><tr><td><code>item_browser_gui.yml</code></td><td>Second</td><td>Lists all items inside one pack.</td></tr></tbody></table><p>The command requires the <code>emakiitem.browse</code> permission (default op) and is <strong>player-only</strong>. <code>/ei browse [page]</code> jumps straight to a page, counted from 1; values below 1 resolve to page 1, and a value beyond the total page count opens an empty page you can leave with the page buttons.</p><h2 id="pack-metadata-pack-yml" tabindex="-1">Pack metadata: <code>pack.yml</code> <a class="header-anchor" href="#pack-metadata-pack-yml" aria-label="Permalink to “Pack metadata: pack.yml”">​</a></h2><p>Every subdirectory under <code>items/</code> may carry a <code>pack.yml</code> defining how that pack&#39;s icon looks on the first level.</p><p>Items placed directly in the <code>items/</code> root also form a &quot;root pack&quot;: its pack id is the empty string, it still appears in the first-level list, and its display name comes from the <code>browser.default_pack_name</code> language key.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;Example Item Pack&lt;/gold&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minecraft-chest&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;&lt;white&gt;%count%&lt;/white&gt; items&lt;/gray&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;dark_gray&gt;Pack id: %pack%&lt;/dark_gray&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;yellow&gt;Click to browse&lt;/yellow&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>display_name</code></td><td>directory name</td><td>Pack name shown on the first level, with MiniMessage support. Empty falls back to the directory name.</td></tr><tr><td><code>icon</code></td><td><code>minecraft-chest</code></td><td>Pack icon as a CoreLib ItemSource shorthand, the same syntax as <code>item.source</code> in an item definition.</td></tr><tr><td><code>lore</code></td><td>item count</td><td>Lore for the pack icon. <code>%count%</code> is the pack&#39;s item count and <code>%pack%</code> is the pack id.</td></tr><tr><td><code>order</code></td><td><code>100</code></td><td>Sort weight on the first level, ascending.</td></tr></tbody></table><p>Three things to note:</p><ul><li><strong>The pack id comes from the directory&#39;s relative path</strong>, independent of <code>pack.yml</code> contents.</li><li>Without a <code>pack.yml</code>, everything falls back: a <code>minecraft:chest</code> icon, the directory name as display name, and lore showing the item count.</li><li><code>pack.yml</code> is <strong>not</strong> read by the item loader as an item definition.</li></ul><p>How deep pack directories may be discovered is controlled by <code>data_directories.max_depth</code> in <code>config.yml</code>; directories beyond that depth do not become separate packs.</p><h2 id="first-level-slot-types" tabindex="-1">First-Level Slot Types <a class="header-anchor" href="#first-level-slot-types" aria-label="Permalink to “First-Level Slot Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>pack_entry</code></td><td>Pack icon area, filled by ascending <code>order</code> (pack id lexicographic order breaks ties), paginated when it overflows. Clicking opens that pack&#39;s second level.</td></tr><tr><td><code>page_prev</code> / <code>page_next</code></td><td>Page turning.</td></tr><tr><td><code>page_info</code></td><td>Page numbers and statistics.</td></tr><tr><td><code>close</code></td><td>Closes the window.</td></tr><tr><td><code>filler</code></td><td>Decorative filler.</td></tr></tbody></table><p>Placeholders available to <code>pack_entry</code> and <code>page_info</code>:</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Where</th><th>Meaning</th></tr></thead><tbody><tr><td><code>%pack%</code></td><td><code>pack_entry</code></td><td>Pack id.</td></tr><tr><td><code>%pack_name%</code></td><td><code>pack_entry</code></td><td>Pack display name.</td></tr><tr><td><code>%pack_lore%</code></td><td><code>pack_entry</code></td><td>Pack lore taken from <code>lore</code> in <code>pack.yml</code>, or fallback text when undefined.</td></tr><tr><td><code>%count%</code></td><td><code>pack_entry</code></td><td>Item count in that pack, the same value as <code>%item_count%</code>.</td></tr><tr><td><code>%item_count%</code></td><td><code>pack_entry</code></td><td>Item count in that pack.</td></tr><tr><td><code>%current_page%</code> / <code>%total_pages%</code></td><td><code>page_info</code></td><td>Current page number and total page count.</td></tr><tr><td><code>%pack_count%</code></td><td><code>page_info</code></td><td>Total pack count.</td></tr><tr><td><code>%item_count%</code></td><td><code>page_info</code></td><td>Total number of loaded item definitions.</td></tr></tbody></table><h2 id="second-level-slot-types" tabindex="-1">Second-Level Slot Types <a class="header-anchor" href="#second-level-slot-types" aria-label="Permalink to “Second-Level Slot Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>item_entry</code></td><td>Item icon area, filled in item id lexicographic order and paginated when it overflows. <strong>Left click takes one piece</strong>, <strong>Shift + left click takes a full stack</strong>; right clicks do nothing.</td></tr><tr><td><code>back</code></td><td>Returns to the first level.</td></tr><tr><td><code>page_prev</code> / <code>page_next</code></td><td>Page turning.</td></tr><tr><td><code>page_info</code></td><td>Page numbers and statistics.</td></tr><tr><td><code>close</code></td><td>Closes the window.</td></tr><tr><td><code>filler</code></td><td>Decorative filler.</td></tr></tbody></table><p>An <code>item_entry</code> icon is <strong>rendered from the item definition itself</strong>; when the slot declares <code>lore</code>, it is appended on top of the item&#39;s own lore.</p><p>On the second level, <code>page_info</code> supports <code>%current_page%</code>, <code>%total_pages%</code>, <code>%pack%</code> (current pack id), <code>%pack_name%</code> (current pack name), and both <code>%item_count%</code> and <code>%count%</code> (item count in the current pack).</p><h2 id="page-capacity-comes-from-the-layout" tabindex="-1">Page Capacity Comes From the Layout <a class="header-anchor" href="#page-capacity-comes-from-the-layout" aria-label="Permalink to “Page Capacity Comes From the Layout”">​</a></h2><p>How many entries fit on a page depends on how many cells <code>pack_entry</code> / <code>item_entry</code> declare in the layout, not on a fixed number. The default layouts give 21 cells on both levels (rows 2 through 4 minus the side borders).</p><p>Changing the cell count of those areas changes pagination directly; the page buttons need no adjustment.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related Pages”">​</a></h2><ul><li><a href="./commands.html">Commands and Permissions</a></li><li><a href="./definitions.html">Item Definitions</a></li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};